\set ON_ERROR_STOP on
begin;
delete from coverage_rule where document_id = (select id from program_document where id::text like 'b3a6d7f5%');
with d as (select id, insurance_company_id from program_document where id::text like 'b3a6d7f5%')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause)
select d.id, d.insurance_company_id, v.pn, v.sc, v.sp, v.vd, v.ct, v.la, v.cl from d cross join (values
('ДМС Стоматология (корпоративная)','стоматология-приёмы','консультация стоматолог терапевт хирург ортопед пародонтолог','covered',null,null,'Раздел «Стоматология» «Услуги врачей-стоматологов: терапевтов, хирургов, пародонтологов, ортопедов»'),
('ДМС Стоматология (корпоративная)','общие-условия','экстренная плановая стоматологическая помощь','covered','обслуживание в «Medswiss Denta» и других профильных клиниках',null,'Раздел «Стоматология» «Экстренная и плановая стоматологическая помощь»'),
('ДМС Стоматология (корпоративная)','стоматология-терапия','обработка пломбирование каналов снятие пломбы','covered',null,null,'Раздел «Терапевтическая стоматология»'),
('ДМС Стоматология (корпоративная)','стоматология-хирургия','удаление зуб','covered',null,null,'Раздел «Хирургическая стоматология» «Удаление зубов, вылущивание кисты при удалении зубов»'),
('ДМС Стоматология (корпоративная)','стоматология-хирургия','вылущивание кисты при удалении','covered',null,null,'Раздел «Хирургическая стоматология» «вылущивание кисты при удалении зубов»'),
('ДМС Стоматология (корпоративная)','стоматология-хирургия','вскрытие абсцесса челюстно-лицевой области','covered',null,null,'Раздел «Хирургическая стоматология» «вскрытие абсцессов челюстно-лицевой области»'),
('ДМС Стоматология (корпоративная)','протезирование','подготовка к протезированию протезирование металлокерамическая коронка','conditional','только если необходимость возникла в результате несчастного случая',null,'Раздел «Ортопедическая стоматология» «если необходимость возникла в результате несчастного случая»'),
('ДМС Стоматология (корпоративная)','пародонтология','заболевания дёсен хирургические методы купирование острых состояний','covered',null,null,'Раздел «Ортопедическая стоматология» «При заболеваниях десен, включая хирургические методы»'),
('ДМС Стоматология (корпоративная)','протезирование','зубопротезирование скидка','excluded','вне страхового покрытия — предоставляется только скидка 5-20% на зубопротезирование','5-20% скидка','Блок «С нами надёжнее» «5-20% скидки на зубопротезирование»'),
('ДМС Стоматология (корпоративная)','общие-условия','страховая сумма','conditional','заявленная страховая сумма по продукту — 1 млн рублей (конкретная сумма определяется договором)','1000000','Блок «С нами надёжнее» «1 млн рублей - страховая сумма»')
) as v(pn, sc, sp, vd, ct, la, cl);
select count(*) as reso_web from coverage_rule where document_id = (select id from program_document where id::text like 'b3a6d7f5%');
commit;
